pub fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    assert!(n > 0, "matrix must have n > 0 rows");
    assert!(input.len() == n, "input must have exactly n rows");
    assert!(j < m, "column index j out of bounds");

    let mut col = Vec::with_capacity(n);
    for i in 0..n {
        assert!(input[i].len() == m, "each row must have exactly m columns");
        col.push(input[i][j]);
    }
    col
}

pub fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    assert!(n > 0, "matrix must have n > 0 rows");
    assert!(input.len() == n, "input must have exactly n rows");

    // Validate row lengths once.
    for row in &input {
        assert!(row.len() == m, "each row must have exactly m columns");
    }

    let mut result: Vec<Vec<i8>> = Vec::with_capacity(m);
    for j in 0..m {
        result.push(get_column(&input, j, m, n));
    }
    result
}